import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

sum_reduce_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void sum_reduce_kernel(const float* input, float* output, 
                                int reduce_dim_size, 
                                int outer_dim, 
                                int inner_dim) {
    const int outer_idx = blockIdx.x;
    const int inner_idx = threadIdx.x;

    if (outer_idx >= outer_dim || inner_idx >= inner_dim) return;

    float sum = 0.0f;
    for(int i = 0; i < reduce_dim_size; ++i) {
        const int input_idx = outer_idx * reduce_dim_size * inner_dim 
                            + i * inner_dim 
                            + inner_idx;
        sum += input[input_idx];
    }

    const int output_idx = outer_idx * inner_dim + inner_idx;
    output[output_idx] = sum;
}

torch::Tensor sum_reduce_cuda(torch::Tensor input, int dim) {
    TORCH_CHECK(dim == 1, "Kernel only optimized for dim=1 reduction");
    auto sizes = input.sizes();
    const int outer_dim = sizes[0];
    const int reduce_dim_size = sizes[1];
    const int inner_dim = sizes[2];

    auto output = torch::zeros({outer_dim, 1, inner_dim}, input.options());

    const dim3 grid(outer_dim);
    const dim3 block(inner_dim);

    sum_reduce_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        reduce_dim_size,
        outer_dim,
        inner_dim
    );

    return output;
}
"""

sum_reduce_cpp_source = "torch::Tensor sum_reduce_cuda(torch::Tensor input, int dim);"

sum_reduce = load_inline(
    name='sum_reduce',
    cpp_sources=sum_reduce_cpp_source,
    cuda_sources=sum_reduce_source,
    functions=['sum_reduce_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.dim == 1:
            return sum_reduce.sum_reduce_cuda(x, self.dim)
        else:
            return torch.sum(x, dim=self.dim, keepdim=True)
